Es_80Vid	BYTEs_Cursor	WORDs_c3ROM	BYTEs_OutputDevice	BLOCK 6s_OutGlobals	BLOCK 4s_InputDevice	BLOCK 6s_InGlobals	BLOCK 4s_ZeroPage	BLOCK 256s_TextBank0	BLOCK $400s_TextBank1	BLOCK $400s_TextBankE0	BLOCK $400s_TextBankE1	BLOCK $400SizeStateRecord	BLOCK 0